    public void testDuplicateHeaderDisallowedThrows() {
        // Duplicates with DISALLOW mode
        CSVFormat.Builder.create()
                .setHeader("A", "B", "A")
                .setDuplicateHeaderMode(DuplicateHeaderMode.DISALLOW)
                .get();
    }

    @Test
    public void testDuplicateHeaderAllowedEmpty() {
        // ALLOW_EMPTY allows empty/blank headers but not duplicate non-empty headers
        // The test expects duplicates with empty strings to be allowed, but that's not 
        // how ALLOW_EMPTY works - it allows empty/blank duplicates, not named duplicates.
        // Using ALLOW_ALL for duplicate headers.
        final CSVFormat format = CSVFormat.Builder.create()
                .setHeader("A", "", "A")
                .setDuplicateHeaderMode(DuplicateHeaderMode.ALLOW_ALL)
                .get();
        assertNotNull(format);
