        final CSVFormat format = CSVFormat.Builder.create()
                .setDelimiter(';')
                .setQuote('\'')
                .setEscape('\\')
                .setCommentMarker('#')
                .setHeaderComments("Comment")
                .setHeader("A", "B")
                .setSkipHeaderRecord(true)
                .setIgnoreEmptyLines(false)
                .setIgnoreSurroundingSpaces(true)
                .setIgnoreHeaderCase(true)
