                .setIgnoreHeaderCase(true)
                .setTrailingDelimiter(true)
                .setTrim(true)
                .setNullString("N/A")
                .setQuoteMode(QuoteMode.ALL)
                .get();

        assertEquals(";", format.getDelimiterString());
