        CSVRecord record1 = it.next();
        assertEquals(1, record1.getRecordNumber());

        assertTrue(it.hasNext());
        CSVRecord record2 = it.next();
        assertEquals(2, record2.getRecordNumber());

        assertTrue(it.hasNext());
