    @Test
    public void testGetRecordNumber() throws IOException {
        CSVParser parser = new CSVParser(new StringReader("a\nb\nc"), CSVFormat.DEFAULT);
        Iterator<CSVRecord> it = parser.iterator();
        assertTrue(it.hasNext());
