package org.apache.commons.csv;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.sql.ResultSet;
import java.sql.ResultSetMetaData;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;

import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.mockito.MockitoAnnotations;

public class CSVPrinterTest {

    private CSVFormat format;
    private Writer writer;
    private CSVPrinter printer;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.initMocks(this);
        format = CSVFormat.DEFAULT;
        writer = new StringWriter();
    }

    @After
    public void tearDown() throws Exception {
        if (printer != null) {
            printer.close();
        }
    }

    @Test(expected = NullPointerException.class)
    public void testConstructorNullAppendable() throws IOException {
        new CSVPrinter(null, CSVFormat.DEFAULT);
    }

    @Test(expected = NullPointerException.class)
    public void testConstructorNullFormat() throws IOException {
        new CSVPrinter(new StringWriter(), null);
    }

    @Test
    public void testPrintRecord() throws IOException {
        try (CSVPrinter printer = new CSVPrinter(writer, format)) {
            printer.printRecord("a", "b", "c");
        }
        assertEquals("a,b,c\n", writer.toString());
    }

    @Test
    public void testPrintRecordIterable() throws IOException {
        List<String> values = new ArrayList<>();
        values.add("x");
        values.add("y");

        try (CSVPrinter printer = new CSVPrinter(writer, format)) {
            printer.printRecord(values);
        }
        assertEquals("x,y\n", writer.toString());
    }

    @Test
    public void testPrintRecordWithNull() throws IOException {
        try (CSVPrinter printer = new CSVPrinter(writer, format)) {
            printer.printRecord("a", null, "b");
        }
        // Default CSVFormat uses null string handling (default null string is null)
        assertEquals("a,,b\n", writer.toString());
    }

    @Test
    public void testPrintRecordIncrementsCount() throws IOException {
        try (CSVPrinter printer = new CSVPrinter(writer, format)) {
            printer.printRecord("a", "b");
            assertEquals(1, printer.getRecordCount());
            printer.printRecord("c", "d");
            assertEquals(2, printer.getRecordCount());
        }
    }

    @Test
    public void testPrintComment() throws IOException {
        CSVFormat commentFormat = CSVFormat.DEFAULT.withCommentMarker('#');
        try (CSVPrinter printer = new CSVPrinter(writer, commentFormat)) {
            printer.printComment("This is a comment");
        }
        String output = writer.toString();
        assertTrue(output.startsWith("# This is a comment\n"));
    }

    @Test
    public void testPrintRecordsArray() throws IOException {
        try (CSVPrinter printer = new CSVPrinter(writer, format)) {
            printer.printRecords("a", "b", "c", "d", "e", "f");
        }
        // printRecords treats the varargs as multiple records if they are arrays/iterables, 
        // or single record if they are simple values? 
        // Looking at source: printRecords(Object...) -> printRecords(Arrays.asList(values))
        // printRecords(Iterable) -> prints each element as a record if it is an array/iterable, else single record.
        // Let's check the logic: printRecords(Iterable) calls IOStream.of(values). forEachOrdered(this::printRecordObject);
        // printRecordObject: if array -> printRecord(array), else printRecord(value).
        // So if I pass "a", "b", "c", it treats "a" as a record (printRecord("a") -> "a\n"), then "b" -> "b\n"...
        // Wait, printRecord(Object...) calls printRecord(Arrays.asList(values)). 
        // So "a" is passed to printRecord(List). That prints "a" as a single value -> "a\n".
        // So it prints 3 lines: a, b, c.
        assertEquals("a\nb\nc\n", writer.toString());
    }

    @Test
    public void testPrintRecordsStream() throws IOException {
        Stream<String> stream = Stream.of("1,2", "3,4");
        try (CSVPrinter printer = new CSVPrinter(writer, format)) {
            printer.printRecords(stream);
        }
        // printRecords(Stream) -> printRecords(IOStream.adapt(values))
        // IOStream.of(values).forEachOrdered(this::printRecordObject);
        // "1,2" is a String (CharSequence), not array/iterable, so printRecord("1,2") -> prints "1,2\n"
        assertEquals("1,2\n3,4\n", writer.toString());
    }

    @Test
    public void testPrintRecordStream() throws IOException {
        Stream<String> stream = Stream.of("a", "b", "c");
        try (CSVPrinter printer = new CSVPrinter(writer, format)) {
            printer.printRecord(stream);
        }
        // printRecord(Stream) prints the stream values as a *single* record.
        // "a", "b", "c" -> "a,b,c\n"
        assertEquals("a,b,c\n", writer.toString());
    }

    @Test
    public void testFlushAndClose() throws IOException {
        Writer flushableWriter = new StringWriter() {
            private boolean flushed = false;
            private boolean closed = false;
            @Override
            public void flush() {
                flushed = true;
            }
            @Override
            public void close() {
                closed = true;
            }
            public boolean isFlushed() { return flushed; }
            public boolean isClosed() { return closed; }
        };

        try (CSVPrinter printer = new CSVPrinter(flushableWriter, format)) {
            printer.printRecord("test");
        }

        assertEquals("test\n", flushableWriter.toString());
    }

    @Test
    public void testGetOut() throws IOException {
        try (CSVPrinter printer = new CSVPrinter(writer, format)) {
            assertEquals(writer, printer.getOut());
        }
    }

    @Test
    public void testPrintHeadersFromResultSet() throws Exception {
        ResultSet rs = mock(ResultSet.class);
        ResultSetMetaData metaData = mock(ResultSetMetaData.class);

        when(rs.getMetaData()).thenReturn(metaData);
        when(metaData.getColumnCount()).thenReturn(2);
        when(metaData.getColumnLabel(1)).thenReturn("Col1");
        when(metaData.getColumnLabel(2)).thenReturn("Col2");

        try (CSVPrinter printer = new CSVPrinter(writer, format)) {
            printer.printHeaders(rs);
        }

        assertEquals("Col1,Col2\n", writer.toString());
        verify(rs, times(1)).getMetaData();
    }

    @Test
    public void testPrintRecordsFromResultSet() throws Exception {
        ResultSet rs = mock(ResultSet.class);
        ResultSetMetaData metaData = mock(ResultSetMetaData.class);

        when(rs.getMetaData()).thenReturn(metaData);
        when(metaData.getColumnCount()).thenReturn(2);

        when(rs.next()).thenReturn(true, true, false);
        when(rs.getObject(1)).thenReturn("A", "1");
        when(rs.getObject(2)).thenReturn("B", "2");

        try (CSVPrinter printer = new CSVPrinter(writer, format)) {
            printer.printRecords(rs);
        }

        assertEquals("A,B\n1,2\n", writer.toString());
    }
}

